void notify_tsk( void )
{		
	for( ; ; )
	{
		Notify_Msg *msg = (Notify_Msg* )q_remove( notify_q_pennding , 0 );
		
		TRACE_DEI_NOTIFY("\n\r[%s]\n\r", notify_txt(msg->nf) );	
			
		reg_execute( notify_table , (Reg_Id)msg->nf , (Reg_Arg)msg->pld );
		
		q_return( (Q_Msg*)msg );		
	}
}

